generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
	std::vector<hpx::future<void>> futures;
	for (auto const& element : x) {
		futures.push_back(hpx::async([=, &z](){
			z[element.index] = alpha * element.value;
		}));
	}
	for (auto const& element : y) {
		futures.push_back(hpx::async([=, &z](){
			z[element.index] += element.value;
		}));
	}
	hpx::wait_all(futures);
}

